size_t renderGateHeartbeatBody(char* out, size_t cap, const char* mac, const char* firmwareVersion,
                               uint64_t uptimeMs, const GateDiagnostics& diagnostics) {
  if (out == nullptr || cap == 0U) {
    return 0U;
  }
  out[0] = '\0';
  if (mac == nullptr || mac[0] == '\0' || firmwareVersion == nullptr) {
    return 0U;
  }

  // Digits from tb::formatU64 and in as `%s`: the ESP32 core's 64-bit printf
  // conversion is a build-time choice this firmware does not make, so `%llu`
  // here is a number that prints as garbage on somebody else's build of the
  // same source. The same rule as devlink's two renderers.
  char uptime[21] = {};
  if (tb::formatU64(uptimeMs, uptime, sizeof(uptime)) == 0U) {
    return 0U;
  }

  // ORDER IS PART OF THE SHAPE: `no_push` then `events_lost`, both after
  // `kind`, both absent at zero. The corpus asserts the bytes, not the keys.
  char noPush[24] = {};
  char eventsLost[28] = {};
  if (!renderCounter(noPush, sizeof(noPush), "no_push", diagnostics.noPush) ||
      !renderCounter(eventsLost, sizeof(eventsLost), "events_lost", diagnostics.eventsLost)) {
    return 0U;
  }

  // The capability LAST: the same suffix, byte for byte, as the court box's —
  // one server reads both.
  const char* caps = diagnostics.codesCapability ? devlink::kCodesCapsSuffix : "";
  const int written = snprintf(
      out, cap, "{\"mac\":\"%s\",\"firmware_version\":\"%s\",\"uptime_ms\":%s,\"kind\":\"gate\"%s%s%s}", mac,
      firmwareVersion, uptime, noPush, eventsLost, caps);
  if (written < 0 || static_cast<size_t>(written) >= cap) {
    out[0] = '\0';
    return 0U;
  }
  return static_cast<size_t>(written);
}

