/// Appends to a bounded buffer; any overflow makes the whole render fail.
class Writer {
public:
  Writer(char* out, size_t cap) : out_(out), cap_(cap) {}

  void text(const char* s) {
    if (failed_) {
      return;
    }
    const size_t n = strlen(s);
    if (len_ + n + 1U > cap_) {
      failed_ = true;
      return;
    }
    memcpy(out_ + len_, s, n + 1U);
    len_ += n;
  }

  void field(const char* key, const char* value) {
    text(",\"");
    text(key);
    text("\":\"");
    text(value);
    text("\"");
  }

  void number(const char* key, uint32_t value) {
    char digits[16] = {};
    const int n = snprintf(digits, sizeof(digits), "%lu", static_cast<unsigned long>(value));
    if (n < 0) {
      failed_ = true;
      return;
    }
    text(",\"");
    text(key);
    text("\":");
    text(digits);
  }

  size_t finish() {
    if (failed_) {
      out_[0] = '\0';
      return 0U;
    }
    return len_;
  }

private:
  char* out_;
  size_t cap_;
  size_t len_ = 0U;
  bool failed_ = false;
};

