namespace {

/// The network facts, and what this boot ran on until its first accepted beat.
void writeNetwork(Writer& w, const GateReport& report) {
  w.number("net_ver", report.netVer);
  w.field("net_src", report.netSrc);
  if (report.restore != nullptr) {
    w.field("restore", report.restore);
  }
}

/// `diag`: the board's own health (device-api.md §13).
void writeDiag(Writer& w, const GateDiag& d) {
  w.text(",\"diag\":{\"reset\":\"");
  w.text(d.reset == nullptr ? "unknown" : d.reset);
  w.text("\"");
  w.number("exc", d.exc);
  w.number("epc1", d.epc1);
  w.number("heap", d.heap);
  w.number("heap_min", d.heapMin);
  w.number("block", d.block);
  w.number("stack_min", d.stackMin);
  w.number("sketch_free", d.sketchFree);
  w.number("flash_mb", d.flashMb);
  w.text("}");
}

/// `drift`: the keys of the previous answer this board could not read (§11.2).
void writeDrift(Writer& w, const Drift& drift) {
  w.text(",\"drift\":[");
  for (uint8_t i = 0U; i < drift.count; ++i) {
    w.text(i == 0U ? "\"" : ",\"");
    w.text(drift.names[i]);
    w.text("\"");
  }
  w.text("]");
}

} // namespace

size_t renderGateHeartbeatV3(char* out, size_t cap, const GateBeat& beat) {
  if (out == nullptr || cap == 0U) {
    return 0U;
  }
  out[0] = '\0';
  const GateReport& report = beat.report;
  if (beat.mac == nullptr || beat.mac[0] == '\0' || beat.firmwareVersion == nullptr ||
      report.netSrc == nullptr) {
    return 0U;
  }
  char uptime[21] = {};
  if (tb::formatU64(beat.uptimeMs, uptime, sizeof(uptime)) == 0U) {
    return 0U;
  }
  Writer w(out, cap);
  w.text("{\"mac\":\"");
  w.text(beat.mac);
  w.text("\",\"firmware_version\":\"");
  w.text(beat.firmwareVersion);
  w.text("\",\"uptime_ms\":");
  w.text(uptime);
  w.text(",\"kind\":\"gate\"");
  if (beat.counters.noPush != 0U) {
    w.number("no_push", saturate(beat.counters.noPush));
  }
  if (beat.counters.eventsLost != 0U) {
    w.number("events_lost", saturate(beat.counters.eventsLost));
  }
  writeNetwork(w, report);
  if (report.diag != nullptr) {
    writeDiag(w, *report.diag);
  }
  if (report.drift != nullptr && report.drift->count > 0U) {
    writeDrift(w, *report.drift);
  }
  w.text(kGateCapsV3);
  w.text("}");
  return w.finish();
}

bool adoptUnlockMs(const char* body, size_t len, uint32_t& unlockMs) {
  if (body == nullptr) {
    return false;
  }

  // BOUNDED TO THE `gate` OBJECT, both ends. devapi::json::findKey is a flat
  // scan by design — the court box reads `button_map` out of the heartbeat's
  // nested `config` with no path — so reading `unlock_seconds` from the whole
  // body would adopt one from anywhere in the document, and reading from the
  // `gate` key onward would adopt one added after the object closed. Either is
  // a lock driven for somebody else's number.
  //
  // This used to be a local colon-requiring copy of findKey, because findKey
  // itself matched a quoted string anywhere and a gate heartbeat opens
  // `{"kind":"gate",…}`. That edge is fixed in devapi now and the copy is gone:
  // one implementation, proven in ../shared/test/test_devapi.
  // AND THE `gate` OBJECT ITSELF IS FOUND AT THE TOP LEVEL (round G4, B2).
  // `findObject` locates its key by the flat scan, so a nested `gate` object
  // placed before the real one was the object this read from — bounded by the
  // hard cap, but still a lock driven for a number the contract did not send.
  size_t innerLen = 0U;
  const size_t at = devapi::json::findTopLevelObject(body, len, "gate", innerLen);
  if (at == devapi::json::kNotFound) {
    return false;
  }

  uint32_t seconds = 0U;
  if (!devapi::json::unsignedField(body + at, innerLen, "unlock_seconds", seconds)) {
    return false;
  }
  // Clamped in SECONDS before the multiply, so a body claiming 4,300,000 cannot
  // wrap into a plausible small number — the same reasoning as Cadence's.
  unlockMs = unlockMsFromSeconds(seconds, kGateConfig.unlockHardCapMs);
  return true;
}

bool unlockSecondsWereClamped(const char* body, size_t len) {
  if (body == nullptr) {
    return false;
  }
  size_t innerLen = 0U;
  const size_t at = devapi::json::findTopLevelObject(body, len, "gate", innerLen);
  if (at == devapi::json::kNotFound) {
    return false;
  }
  uint32_t seconds = 0U;
  if (!devapi::json::unsignedField(body + at, innerLen, "unlock_seconds", seconds)) {
    return false;
  }
  // AGAINST THE SAME BOUNDS THE CLAMP USES, derived rather than written out, so
  // a change to either end of the contract's range cannot leave this predicate
  // answering about the old one.
  const uint32_t minSeconds = kMinUnlockMs / 1000UL;
  const uint32_t maxSeconds = kGateConfig.unlockHardCapMs / 1000UL;
  return seconds < minSeconds || seconds > maxSeconds;
}

bool adoptFaultSettings(const char* body, size_t len, GateFaultSettings& settings) {
  if (body == nullptr) {
    return false;
  }
  // BOUNDED TO THE TOP-LEVEL `gate` OBJECT, both ends, for exactly the reason
  // adoptUnlockMs is: `findKey` is a flat scan by design, so a key of this name
  // added anywhere else in a future response — or in a nested object placed
  // before the real one, which is round G4's B2 — is not this one.
  size_t innerLen = 0U;
  const size_t at = devapi::json::findTopLevelObject(body, len, "gate", innerLen);
  if (at == devapi::json::kNotFound) {
    return false;
  }

  bool read = false;

  // INDEPENDENTLY, AND THAT IS THE WHOLE POINT OF TWO STATEMENTS RATHER THAN
  // ONE. An API that sends the rate and not the switch must not reset the
  // switch, and an absent key is not "false" — it is silence.
  bool reporting = settings.reporting;
  if (devapi::json::boolField(body + at, innerLen, "device_fault_reporting", reporting)) {
    settings.reporting = reporting;
    read = true;
  }

  uint32_t perHour = 0U;
  if (devapi::json::unsignedField(body + at, innerLen, "device_fault_max_per_hour", perHour)) {
    // Clamped BEFORE it can reach a divisor: windowMs() is 3600000 / this, and
    // a zero is a division by zero rather than a slow board. The same rule as
    // clamping unlock_seconds in seconds before the multiply.
    const uint32_t bounded = perHour < kMinFaultMaxPerHour
                                 ? kMinFaultMaxPerHour
                                 : (perHour > kMaxFaultMaxPerHour ? kMaxFaultMaxPerHour : perHour);
    settings.maxPerHour = static_cast<uint16_t>(bounded);
    read = true;
  }

  return read;
}

